    "grammar": "【単語解説】\r\n・succeed in：[動] 〜に成功する\r\n・mission：[名] 使命、任務\r\n・single-minded：[形] 一意専心の、脇目も振らない\r\n・devotion：[名] 献身、愛情\r\n\r\n【文法解説】\r\n・不定詞の副詞的用法：To succeed...（成功するためには）。文頭に置くことで目的を強調しています。\r\n・助動詞 must：強い義務（〜しなければならない）を表し、目標達成の絶対条件を提示しています。\r\n\r\n【背景・ニュアンス】\r\nインドの第11代大統領であり、宇宙工学の父とも呼ばれるA.P.J.アブドゥル・カラームの言葉。大きな使命を達成するための唯一の条件は、目標に対して一切の妥協やよそ見をせず、「一意専心（single-minded）」の献身と情熱を注ぎ込むことだという、強烈な集中力のススメです。",
