    "grammar": "【単語解説】\r\n・whether A or B：AかBか\r\n・knock down：[動] 打ち倒す\r\n・get up：[動] 起き上がる\r\n\r\n【文法解説】\r\n・It is not A... it is B：AではなくBだ。\r\n・get + 過去分詞の受動態：get knocked down で「（他からの力によって）打ち倒される」。\r\n・対比：knocked down（受動的な不運）と get up（自発的な行動）を whether 節で美しく対比させています。\r\n\r\n【背景・ニュアンス】\r\nアメリカンフットボールの伝説的コーチ、ヴィンス・ロンバルディの言葉。生きていれば不運や失敗によって打ち倒される（knocked down）のは当然のこと。問われるべきは、倒れた事実ではなく、そこから「自らの意志で立ち上がる（get up）かどうか」だという不屈の精神です。",
