    "grammar": "【単語解説】\r\n・sum up：[動] 要約する\r\n・go on：[動] 続く、進み続ける\r\n\r\n【文法解説】\r\n・関係代名詞の省略：everything (that) I've learned（私がこれまでに学んだすべてのこと）。\r\n・コロン（:）：コロンの後ろの it goes on（それは続いていく）が、前文の everything の具体的な内容（答え）となっています。\r\n\r\n【背景・ニュアンス】\r\nアメリカの詩人ロバート・フロストの言葉。人生について数多くの複雑なことを経験し学んできたが、最終的に出た結論はたったの3語（it goes on）。どんな悲劇があろうと、どんな成功があろうと、人生という時間はただ「容赦なく前へ進み続ける」という真理です。",
