    "grammar": "【単語解説】\r\n・whenever：[接] 〜する時はいつでも\r\n・possible：[形] 可能な\r\n\r\n【文法解説】\r\n・副詞節の省略：whenever (it is) possible（可能な時はいつでも）。\r\n・断定の文：It is always possible.（それは『常に』可能である）。この短い2文目が強力なパンチラインになっています。\r\n\r\n【背景・ニュアンス】\r\nダライ・ラマ14世の言葉。「可能な限り、他人に優しく（kind）しなさい」。この一見普通の道徳的アドバイスに、「そして、優しくすることは『常に（always）』可能である」という一文を付け加えることで、どんな状況でも愛と思いやりを選択できる人間の心の自由と強さを説いています。",
