    "grammar": "【単語解説】\r\n・fortune：[名] 運命の女神、幸運\r\n・favor：[動] 好む、〜に味方する\r\n・bold：[形] 大胆な、勇敢な\r\n\r\n【文法解説】\r\n・The + 形容詞：the bold で「大胆な人々（the bold people）」という複数名詞の扱いになります。\r\n・擬人化：Fortune（幸運）を主語にし、自らの意志で味方を選ぶ女神のように扱っています。\r\n\r\n【背景・ニュアンス】\r\n古代ローマの詩人ウェルギリウスらが残したラテン語の格言（Audentes fortuna iuvat）の英訳。運命や幸運というものは、安全地帯で怯えている人間には決して微笑まない。リスクを取って「大胆に行動する者（the bold）」にこそ味方をするという力強い教訓です。",
